const fs = require('fs'); const { PNG } = require('pngjs'); const pixelmatch = require('pixelmatch');
const ref = PNG.sync.read(fs.readFileSync('e2e/home-v2/fixtures/navbar-reference.png'));
const act = PNG.sync.read(fs.readFileSync('e2e/artifacts/task2468-navbar-visual/navbar-visual-1920.png'));
const w=ref.width,h=ref.height,total=w*h,boxes=[[494,24,38,34],[634,24,38,34],[750,24,38,34],[871,24,38,34],[997,24,38,34],[1127,24,38,34],[1256,24,38,34],[1385,24,38,34],[1516,24,38,34],[1640,24,38,34],[1688,38,28,34],[1855,22,36,36]];
const a=Buffer.from(ref.data),b=Buffer.from(act.data),mask=new Uint8Array(total);
for(const [x0,y0,bw,bh] of boxes)for(let y=Math.max(0,y0);y<Math.min(h,y0+bh);y++)for(let x=Math.max(0,x0);x<Math.min(w,x0+bw);x++){const p=y*w+x,i=p*4;mask[p]=1;a[i]=a[i+1]=a[i+2]=a[i+3]=0;b[i]=b[i+1]=b[i+2]=b[i+3]=0;}
let masked=0;for(const value of mask)masked+=value;const all=pixelmatch(ref.data,act.data,Buffer.alloc(total*4),w,h,{threshold:0.1,includeAA:false}),rest=pixelmatch(a,b,Buffer.alloc(total*4),w,h,{threshold:0.1,includeAA:false});console.log(JSON.stringify({overallSimilarity:((1-all/total)*100).toFixed(3)+'%',maskedIconPixels:masked,withoutIconSimilarity:((1-rest/(total-masked))*100).toFixed(3)+'%'},null,2));
'@; node -e $pixelScript
